// Parse container images from qe-ceph-manifest YAML files
// Returns a map of images categorized by root-level keys (e.g., z0, rc, nightly, released)

def call(Map parameters) {
    // Get manifest directory path
    def manifestDir = parameters.get("manifestDir")
    if (!manifestDir) {
        throw new RuntimeException(
            "Mandatory parameter 'manifestDir' is not provided"
        )
    }

    // Get vendor (ibm or redhat)
    def vendor = parameters.get("vendor")
    if (!vendor) {
        throw new RuntimeException(
            "Mandatory parameter 'vendor' is not provided"
        )
    }

    // Get release version
    def releaseVersion = parameters.get("releaseVersion")
    if (!releaseVersion) {
        throw new RuntimeException(
            "Mandatory parameter 'releaseVersion' is not provided"
        )
    }

    // Construct YAML file path
    def yamlFile = "${manifestDir}/${vendor}/${releaseVersion}.yaml"
    
    // Check if file exists
    if (!fileExists(yamlFile)) {
        echo "Warning: Manifest file ${yamlFile} does not exist"
        return [:]
    }

    echo "Parsing manifest file: ${yamlFile}"

    // Read and parse YAML file
    def manifestContent = readYaml file: yamlFile

    // Initialize result map - will be populated dynamically
    def result = [:]
    def totalImages = 0

    // Iterate through all root-level keys in the YAML
    manifestContent.each { rootKey, rootValue ->
        // Initialize list for this root key
        result[rootKey] = []
        
        // Check if this root key has an 'images' section
        if (rootValue && rootValue instanceof Map && rootValue.containsKey('images')) {
            def images = rootValue['images']
            
            // Images can be a map (key: value) or list
            if (images instanceof Map) {
                // Extract image URLs from map values
                images.each { key, value ->
                    if (value && value.toString().trim()) {
                        def imageUrl = value.toString().trim()
                        result[rootKey] << imageUrl
                        totalImages++
                    }
                }
            } else if (images instanceof List) {
                // Extract image URLs from list
                images.each { image ->
                    if (image && image.toString().trim()) {
                        def imageUrl = image.toString().trim()
                        result[rootKey] << imageUrl
                        totalImages++
                    }
                }
            }
        }
    }

    // Log summary
    echo "Parsed images from ${vendor}/${releaseVersion}.yaml:"
    result.each { section, imageList ->
        if (imageList.size() > 0) {
            echo "  - ${section}: ${imageList.size()} images"
        }
    }
    echo "  Total images: ${totalImages}"

    return result
}
